import runtimeEnvKeys from './runtime-env-keys.json';

export type RuntimeEnvKey = (typeof runtimeEnvKeys)[number]['key'];

export type RuntimeEnvValues = Partial<Record<RuntimeEnvKey, string>>;

declare global {
  interface Window {
    __DOCBITS_ENV__?: RuntimeEnvValues;
  }
}

// Every key is listed literally: the bundler replaces `process.env.X` textually,
// so a computed lookup would survive the build as a real (empty) process access.
//
// Read on each call, not once at module load. The replacement is textual either
// way, so the built bundle is identical — but a value captured at import time
// is whatever the process happened to hold when the module was first evaluated,
// which no test can then change.
const buildTimeEnv = (): RuntimeEnvValues => ({
  APP_VUE_BRANCH: process.env.APP_VUE_BRANCH,
  APP_VUE_STAGE: process.env.APP_VUE_STAGE,
  APP_VUE_ENVIRONMENT: process.env.APP_VUE_ENVIRONMENT,
  APP_VUE_CLIENT_ID: process.env.APP_VUE_CLIENT_ID,
  APP_VUE_CLIENT_SECRET: process.env.APP_VUE_CLIENT_SECRET,
  APP_VUE_RECAPTCHA_KEY: process.env.APP_VUE_RECAPTCHA_KEY,
  APP_VUE_GOOGLE_CLIENT_ID: process.env.APP_VUE_GOOGLE_CLIENT_ID,
  APP_VUE_LINKEDIN_CLIENT_ID: process.env.APP_VUE_LINKEDIN_CLIENT_ID,
  APP_VUE_MICROSOFT_CLIENT_ID: process.env.APP_VUE_MICROSOFT_CLIENT_ID,
  APP_VUE_EMAIL_ENCRYPTION_KEY: process.env.APP_VUE_EMAIL_ENCRYPTION_KEY,
  APP_VUE_WEB_SOCKET_URL: process.env.APP_VUE_WEB_SOCKET_URL,
  APP_VUE_USER_MOCK_DATA: process.env.APP_VUE_USER_MOCK_DATA,
  APP_VUE_TABLE_EXTRACTION: process.env.APP_VUE_TABLE_EXTRACTION,
  APP_VUE_RELEASE_CHANNEL_READONLY: process.env.APP_VUE_RELEASE_CHANNEL_READONLY,
  SENTRY_ENABLED: process.env.SENTRY_ENABLED,
  SENTRY_DSN: process.env.SENTRY_DSN,
  SENTRY_TRACES_SAMPLE_RATE: process.env.SENTRY_TRACES_SAMPLE_RATE,
  VITE_ENABLE_DEBUG_LOGS: process.env.VITE_ENABLE_DEBUG_LOGS,
  VITE_ENABLE_INFO_LOGS: process.env.VITE_ENABLE_INFO_LOGS,
  VITE_LOG_LEVEL: process.env.VITE_LOG_LEVEL,
});

export const RUNTIME_ENV_KEYS: RuntimeEnvKey[] = runtimeEnvKeys.map(entry => entry.key);

function injectedValue(key: RuntimeEnvKey): string | undefined {
  if (typeof window === 'undefined') return undefined;
  return window.__DOCBITS_ENV__?.[key];
}

/**
 * The deployed environment's value for `key`.
 *
 * `/env-config.js` is written per environment when the build is deployed and
 * runs before the app bundle, so it wins over anything the build was compiled
 * with. The build-time value is only a fallback for `quasar dev` and unit tests.
 */
export function runtimeEnv(key: RuntimeEnvKey): string | undefined {
  const injected = injectedValue(key);
  if (injected !== undefined && injected !== '') return injected;

  const compiled = buildTimeEnv()[key];
  return compiled === '' ? undefined : compiled;
}

/**
 * The deployed environment's value for `key`, or a thrown error.
 *
 * For the values that decide WHICH BACKEND the app talks to. A missing one
 * used to fall through to an empty string, which is the same prefix
 * production uses — so a container with no environment quietly talked to
 * production while calling itself dev. There is no safe default for a
 * question like that, so there is no default.
 */
export function runtimeEnvRequired(key: RuntimeEnvKey): string {
  const value = runtimeEnv(key);
  if (value !== undefined && value !== '') return value;

  throw new Error(
    `[DocBits] ${key} is not set, so this build does not know which environment ` +
      'it is running in. It refuses to start rather than guess — guessing once ' +
      'meant talking to production.\n\n' +
      'The bundle deliberately carries no environment: one build serves dev, ' +
      'sandbox, stage and production, and env-config.js supplies the rest at ' +
      'runtime.\n\n' +
      '  deployed: the container writes env-config.js at start from its App ' +
      'Platform variables (deploy/docker-entrypoint.d/40-env-config.sh)\n' +
      '  local:    node scripts/apply-env-config.js --env env/deploy.<stage>.env',
  );
}

export function runtimeEnvOr(key: RuntimeEnvKey, fallback: string): string {
  return runtimeEnv(key) ?? fallback;
}

export function runtimeEnvFlag(key: RuntimeEnvKey): boolean {
  return runtimeEnv(key) === 'true';
}
