// Per-module imports, not the `crypto-js` default export: this file is on the
// boot path (api-base-url.ts decrypts the stored region), and the default
// export bundles every cipher, hash and encoder crypto-js ships (CORE-6328).
// AES-ECB with PKCS7 padding and a UTF-8 key — output is byte-identical.
import AES from 'crypto-js/aes';
import Utf8 from 'crypto-js/enc-utf8';
import ECB from 'crypto-js/mode-ecb';
import Pkcs7 from 'crypto-js/pad-pkcs7';
import { runtimeEnv } from 'src/config/runtime-env';

export default {
  data() {
    return {
      ENCRYPTION_KEY: Utf8.parse(runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY')),
    };
  },
  methods: {
    encryptPassword(password: string): string {
      return AES.encrypt(password, this.ENCRYPTION_KEY, {
        mode: ECB,
      }).toString();
    },

    decryptPassword(encrypted: string): string {
      const bytes = AES.decrypt(encrypted, this.ENCRYPTION_KEY, { mode: ECB });
      return bytes.toString(Utf8);
    },

    generalEncryption(fieldValue: any) {
      const EMAIL_ENCRYPTION_KEY = runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY');
      const key = Utf8.parse(String(EMAIL_ENCRYPTION_KEY));
      return AES.encrypt(String(fieldValue), key, {
        mode: ECB,
        padding: Pkcs7,
      });
    },

    generalDecryption(fieldValue: any) {
      const EMAIL_ENCRYPTION_KEY = runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY');
      const key = Utf8.parse(String(EMAIL_ENCRYPTION_KEY));
      return AES.decrypt(String(fieldValue), key, { mode: ECB });
    },
  },
};
