// Inbound (MailerSend) pipeline is REGION-CORRECT since DOCB-13674: each org
// receives mail on its own regional inbound domain (plus a worker-level
// forward safety net for mail still addressed to the old EU domain), so
// configs, import-log rows and original .eml files live in the org's own
// regional import-email database. The inbound_* endpoints therefore follow
// the session region like every other service — the former eu. pin
// (DOCB-13609/13604, when the pipeline was EU-central) would now show US
// organisations an EU log that no longer receives their imports.
export const INBOUND_EMAIL_URL        = buildServiceUrl('import-email');
