// ─── Non-regional infrastructure ─────────────────────────────────────────

// NOTE: this prefix is NOT the same rule as api-base-url.ts's. These hosts are
// polydocs.io / cloudintegration.eu, not *.docbits.com, and there `prod` keeps
// its prefix (prod.terraform.polydocs.io) while on docbits.com it drops it.
// Only `ruiz` is unprefixed in both. The rule is left exactly as it was; the
// only thing that changed is that a MISSING value now throws instead of
// producing the same empty prefix as production.
const rawBranch = runtimeEnvRequired('APP_VUE_BRANCH');
// ruiz customer points at production URLs even though APP_VUE_BRANCH is set.
const branch = rawBranch === 'ruiz' ? '' : rawBranch + '.';

// True only when running against the customer-facing Sandbox env
// (APP_VUE_BRANCH=sandbox). Dev and Stage are not Sandbox.
export function isSandboxEnvironment(): boolean {
  return getCurrentEnvironment() === 'sandbox';
}

const TERRAFORM_URL = 'https://' + branch + 'terraform.polydocs.io';
const INSIGHT_URL = 'https://' + branch + 'insight.polydocs.io';

export const FELLOWKV2_URL =
  'https://' + branch + 'fellowkv2.cloudintegration.eu';
export const SUPPORT_URL =
  'https://' + branch + 'cloudintegration.eu/doc2_support';

const CLOUD_INTEGRATION_URL = 'https://docbits.com/';

// Discord Bot Invite URL (per-environment client IDs)
const DISCORD_BOT_CLIENT_IDS: Record<string, string> = {
  'dev.': '1487054980803461120',
  'stage.': '', // TODO: add stage bot client ID
  'sandbox.': '', // TODO: add sandbox bot client ID
  'demo.': '', // TODO: add demo bot client ID
};
const discordClientId = DISCORD_BOT_CLIENT_IDS[branch] ?? ''; // default: prod
export const DISCORD_BOT_INVITE_URL = discordClientId
  ? `https://discord.com/oauth2/authorize?client_id=${discordClientId}&permissions=277025508352&scope=bot+applications.commands+guilds+messages.read`
  : '';

// Returns 'dev', 'stage', 'prod', etc. (no trailing dot).
//
// No `|| 'dev'` default: it used to mean one missing APP_VUE_BRANCH produced
// two different answers in the same module — hosts resolved to production
// while this reported 'dev'. A missing value now throws in one place.
export function getCurrentEnvironment(): string {
  const raw = runtimeEnvRequired('APP_VUE_BRANCH');
  return raw.endsWith('.') ? raw.slice(0, -1) : raw;
}

