// Every URL in apiInternal was built from the region-baked constants above
// (DOC2API_URL, OPERATOR_URL, …), so no per-access rewriting is needed.
// A region switch reloads the page (see setApiRegion), which rebuilds them.
export const api = apiInternal;

// CORE-6326: APIs.ts must stay a leaf module. quasar.config.cjs pins it into
// the boot chunk `api-config`, and Rollup moves every module reachable only
// through a pinned file into that chunk — a static import of the service
// barrel here dragged ~700 store/service/SDK modules onto the login page.
// Resolve the service at call time instead (src/pages/__tests__/
// APIs.leaf-module.unit.spec.ts guards this).
export async function getAuthorizationToken() {
  const { authApiService } = await import('src/services');
  const token = await authApiService.getToken();
  return token;
}

export function getClientAuthorization() {
  // Fixed client credentials with corrected secret (788 not 7x8)
  const clientId = runtimeEnv('APP_VUE_CLIENT_ID') || 'DocBits';
  const clientSecret =
    runtimeEnv('APP_VUE_CLIENT_SECRET') ||
    'dfyykB8aHbACjJ9VV788tiOkWMAiqTtzSYIvvUFdNssPujYD';

  // Ensure we always use the correct client secret if the environment has the old one
  const correctedSecret = clientSecret.includes('7x8')
    ? 'dfyykB8aHbACjJ9VV788tiOkWMAiqTtzSYIvvUFdNssPujYD'
    : clientSecret;

  return 'Basic ' + btoa(clientId + ':' + correctedSecret);
}

export function getVendorsListAPI(text: string) {
  return (
    DOC2API_URL +
    '/fuzzy/get_vendors_list?keyword=' +
    text +
    '&address_type=Discrete&skip=0&limit=15'
  );
}

export function getMediVendorsListAPI(text: string) {
  return (
    DOC2API_URL + '/medi/get_customer_list?keyword=' + text + '&skip=0&limit=30'
  );
}

export function getRegexSaveUrl(type: string) {
  let url = api.update_document_type_regexes;
  if (type === 'filter_regexes') {
    url = api.update_fellow_kv_regexes;
  }

  return url;
}
