// Region routing for *.docbits.com services.
//
// Region is decided once per session from the /profile call after login,
// stored encrypted in LocalStorage, and baked into every URL constant at
// module-load time (see APIs.ts). The post-/profile call never reloads —
// URL constants are correct for the persisted region from prior sessions,
// and a first-time login self-corrects on the next page load. A LATER
// region change (future sub-org switch) reloads so constants rebuild —
// no listeners, no Proxy, no per-request rewriting.

import Utf8 from 'crypto-js/enc-utf8';
import { LocalStorage, SessionStorage } from 'quasar';
import encryptionUtil from 'src/utils/encryptionUtil';

import { runtimeEnv, runtimeEnvRequired } from 'src/config/runtime-env';
// The encryption helpers live on the legacy Vue mixin's `methods` block.
// They don't reference `this`, so we can call them straight off the default
// export — no need to instantiate the mixin or duplicate the primitives.
// Accessed lazily at the call sites below so tests that stub `encryptionUtil`
// with `{ default: {} }` (export-configuration suite) don't crash on import.

export const REGION_STORAGE_KEY = 'api_region';
export const AUTH_REGION_STORAGE_KEY = 'auth_region';
export const CHANNEL_STORAGE_KEY = 'release_channel';

// Written by prepare-dashboard right before the cross-region hard reload and
// removed once the target region accepts the token.
export const REGION_SWITCH_STORAGE_KEY = 'region_switch';

export type ApiRegion = 'eu' | 'us';
export type ReleaseChannel = 'vesta' | 'nova';

// Stages that participate in region routing. Adding a stage here is enough
// to opt it in; everything else (stage, demo, local) stays unprefixed.
// prod uses APP_VUE_BRANCH='prod', which maps to no host prefix, so the URL
// is https://<region>.<service>.docbits.com.
export const REGIONAL_STAGES = ['prod', 'dev', 'sandbox'] as const;

// Every *.docbits.com service that gets the region prefix on regional
// stages. Used as the source of truth for the contract spec and any future
// service-list rendering. auth is intentionally NOT in this list.
export const REGIONAL_SERVICES = [
  'api',
  'api-sticky',
  'docflow',
  'operator',
  'idea',
  'autoaccounting',
  'pomatch',
  'import-ftp',
  'import-email',
  'docnet',
  'docnet-sticky',
  'fulltext',
] as const;

// Branches whose *.docbits.com hosts carry no subdomain prefix: production
// is `api.docbits.com`, not `prod.api.docbits.com`, and the ruiz tenant
// rides the same hosts.
//
// Production is named EXPLICITLY here. It used to be expressed as an empty
// APP_VUE_BRANCH, which made "production" and "nobody told me which
// environment this is" the same value — so a container with no config
// resolved to production while reporting itself as dev. The two are now
// separate: an absent value throws, and only the literal string 'prod'
// selects production.
const UNPREFIXED_BRANCHES = ['prod', 'ruiz'] as const;

export function branchPrefix(rawBranch: string): string {
  return (UNPREFIXED_BRANCHES as readonly string[]).includes(rawBranch)
    ? ''
    : rawBranch + '.';
}

const stage = runtimeEnvRequired('APP_VUE_STAGE');
const rawBranch = runtimeEnvRequired('APP_VUE_BRANCH');

const branch = branchPrefix(rawBranch);

export function isRegionalStage(): boolean {
  return (REGIONAL_STAGES as readonly string[]).includes(stage);
}

/**
 * The branch subdomain prefix for *.docbits.com hosts.
 *
 * Returns `'<branch>.'` for non-production branches (e.g. `'dev.'`,
 * `'stage.'`) and `''` for production (`prod`/`ruiz`) so prod hosts stay
 * clean — e.g. `inbound.docbits.com`, not `prod.inbound.docbits.com`.
 */
export function getBranchPrefix(): string {
  return branch;
}

/**
 * Decrypts the persisted region or falls back to 'eu' if nothing is
 * stored, the value is tampered (plaintext), or decryption returns
 * an unrecognised value.
 */
export function getCurrentApiRegion(): ApiRegion {
  const stored = LocalStorage.getItem(REGION_STORAGE_KEY) as string | null;
  if (!stored) {
    return 'eu';
  }

  let plain = '';
  try {
    plain = encryptionUtil.methods
      .generalDecryption(stored)
      .toString(Utf8);
  } catch {
    // Tampered or non-ciphertext value → fall through to default.
  }
  if (plain === 'us' || plain === 'eu') {
    return plain;
  }

  return 'eu';
}

/**
 * The org's inbound email address, on its REGION's inbound domain
 * (DOCB-13674): `us` orgs get `us.<branch>.inbound.docbits.com` so the mail is
 * delivered directly to the US import-email instance and both the documents
 * AND the import log live in the org's region; `eu` stays on the unprefixed
 * default domain (`<branch>.inbound.docbits.com`). Non-regional stages
 * (stage/demo/local) have no `us.` inbound domains at all, so the prefix is
 * only applied on regional stages — a stale `us` region in LocalStorage must
 * never render a nonexistent address there. Pure so it is unit-testable
 * without mounting the settings component.
 */
export function composeInboundAddress(
  orgId: string,
  region: ApiRegion = getCurrentApiRegion(),
  branchPrefix: string = getBranchPrefix(),
  regional: boolean = isRegionalStage(),
): string {
  const regionPrefix = regional && region === 'us' ? 'us.' : '';
  return `${orgId}@${regionPrefix}${branchPrefix}inbound.docbits.com`;
}

/**
 * The active organisation's release channel, read from LocalStorage where it
 * was persisted at login from `/v2/users/me/organisations` (see setChannel).
 * Not encrypted — `vesta`/`nova` is not sensitive. Defaults to `vesta` (the
 * normal hosts) for any org that never opted in to nova.
 */
export function getCurrentChannel(): ReleaseChannel {
  const stored = LocalStorage.getItem(CHANNEL_STORAGE_KEY) as string | null;
  return stored === 'nova' ? 'nova' : 'vesta';
}

// The channel the module-load-time URL constants (DOC2API_URL, WEB_SOCKET_URL,
// …) were actually built with — captured once at import. buildServiceUrl reads
// getCurrentChannel() at module load, so this equals the channel baked into
// every service URL for this page load.
const loadedChannel: ReleaseChannel = getCurrentChannel();

// Hostnames that can only ever be serving ONE bundle. `.local` is the mDNS
// suffix (a Mac's own name, used to open the dev server from a phone); a
// `*.localhost` name is the same machine by definition.
const LOCAL_HOSTNAMES = ['localhost', '127.0.0.1', '::1'] as const;

/**
 * Whether THIS origin actually serves the pinned `/nova/` bundle.
 *
 * The vesta/nova split is a deploy artefact, not a property of the app: CI
 * builds a second bundle with `NOVA_BUILD=1` (publicPath `/nova/`, see
 * quasar.config.cjs) and nginx publishes it at `./nova/` next to the root
 * bundle (deploy/nginx.conf). Nothing local produces it — `quasar dev` serves
 * exactly one bundle at `/` with the Vue Router base `/`, and `serve:dist`
 * serves the single build that was just made. So sending a nova org to
 * `/nova/dashboard` there navigates to a path that no bundle and no route
 * owns: the app is simply gone, and only clearing `release_channel` from
 * LocalStorage by hand brings it back. Which developer this hits is decided by
 * which release channel their own organisation happens to be on — nothing
 * about their checkout.
 *
 * Deliberately a HOSTNAME check, not a stage check. Local work runs with
 * `APP_VUE_STAGE=dev` on purpose (docs/runtime-env-config.md): it talks to the
 * dev backend, and `local` is not a usable stage for host building —
 * branchPrefix('local') would resolve every service to a
 * `local.*.docbits.com` that does not exist. So the stage says nothing about
 * which bundles were published; the server that answered does. One signal,
 * and it is the one the browser can actually observe.
 *
 * Unknown hosts answer `true`: a wrong `false` would strand a real nova
 * customer on the vesta bundle, while a wrong `true` only reproduces the
 * behaviour that existed before this guard.
 */
export function hasPinnedNovaBundle(
  hostname: string = typeof window !== 'undefined'
    ? window.location?.hostname || ''
    : '',
): boolean {
  const host = hostname.toLowerCase().replace(/^\[|\]$/g, '');
  if (!host) return true;
  if ((LOCAL_HOSTNAMES as readonly string[]).includes(host)) return false;

  return !host.endsWith('.localhost') && !host.endsWith('.local');
}

/**
 * Persist the active org's release channel and, if it differs from the channel
 * the URL constants were BUILT with (loadedChannel), reload once so
 * buildServiceUrl re-runs with the new channel.
 *
 * Why compare against loadedChannel, not "did it change since the last call":
 * on a fresh login the session's storage is empty, so the URLs are built as
 * `vesta`; the profile then reports `nova` and setChannel('nova') is
 * called — that FIRST call must still reload, otherwise the whole session keeps
 * hitting the vesta hosts even though the org is nova (the bug: nova never
 * took effect after login). After the reload the module re-loads with the
 * persisted channel, so loadedChannel matches and no further reload happens
 * (converges, no loop). Same handling covers the settings-card switch.
 */
export function setChannel(channel: ReleaseChannel | undefined | null): void {
  const resolved: ReleaseChannel = channel === 'nova' ? 'nova' : 'vesta';

  try {
    LocalStorage.set(CHANNEL_STORAGE_KEY, resolved);
  } catch (error) {
    console.error('[Channel] Failed to persist release_channel:', error);
    return;
  }

  if (typeof window === 'undefined' || !window.location) {
    return;
  }

  // DEVO-135 nova-frontend split (mirrors the retired DOCB-13416 frozen
  // split): a nova org must be served the pinned nova bundle under /nova/
  // (the nova channel's release name, see src/utils/release-names.ts), a
  // vesta org the root bundle. This is a full-document, same-origin
  // navigation, so localStorage/token survive and the target bundle re-reads
  // the persisted channel (converges: on the nova bundle `inNova` is already
  // true → no further redirect). The current in-app route is preserved
  // (/dashboard → /nova/dashboard and back). Read location defensively so a
  // partial mock (or an exotic host) can never crash channel persistence.
  const loc = window.location;
  const pathname = loc.pathname || '/';
  const inNova = pathname.startsWith('/nova/');
  const rest = (loc.search || '') + (loc.hash || '');
  const canAssign = typeof loc.assign === 'function';

  // Local development: the root bundle is the ONLY bundle this origin has
  // (hasPinnedNovaBundle). The channel is still persisted above — the
  // settings card and anything else that reads it stays truthful — but the
  // bundle redirect is skipped, because there is nothing at /nova/ to redirect
  // to. A `/nova/` path left over from an earlier session (or a bookmark
  // copied from dev.docbits.com) is stripped instead, so a developer who is
  // already stuck there is carried back to the one bundle that exists.
  if (!hasPinnedNovaBundle()) {
    if (inNova && canAssign) {
      loc.assign(pathname.replace(/^\/nova/, '') + rest);
    }
    return;
  }

  if (resolved === 'nova' && !inNova && canAssign) {
    loc.assign('/nova' + pathname + rest);
    return;
  }
  if (resolved === 'vesta' && inNova && canAssign) {
    loc.assign(pathname.replace(/^\/nova/, '') + rest);
    return;
  }

  // Already on the correct bundle: keep the original behaviour of reloading
  // once when the channel differs from what the module-load-time service URLs
  // were built with, so buildServiceUrl re-runs with the right channel.
  if (resolved !== loadedChannel && typeof loc.reload === 'function') {
    loc.reload();
  }
}

export function clearPersistedChannel(): void {
  LocalStorage.remove(CHANNEL_STORAGE_KEY);
}

/**
 * Build the URL for a *.docbits.com service:
 *   regional stage  →  https://<region>.<branch><service>.docbits.com
 *   other stage     →  https://<branch><service>.docbits.com
 *
 * `<service>` is the bare subdomain — e.g. `'api'`, `'operator'`,
 * `'fulltext'` — and must be one of REGIONAL_SERVICES.
 *
 * One API host per region-env. Channel routing (vesta/nova) is no longer
 * expressed as a client-side host split: Kong now resolves the channel
 * server-side via token introspection (DOCB-13416), so the frontend always
 * calls the plain regional host regardless of the org's release channel.
 * The old `forceLatest` opt is gone — a nova org no longer has a separate
 * host to pin away from, and the one endpoint that needed the shared/vesta
 * registry (`/service_versions`) is exempted at the gateway (Kong) instead.
 *
 * `regionOverride` pins the host to one region regardless of the user's
 * session region (DOCB-13609): the MailerSend inbound-email pipeline runs
 * centrally on the EU import-email instance — inbound configs, import-log
 * rows and the stored original .eml all live in the EU database — so the
 * inbound_* endpoints must always be read from `eu.` even for a US-region
 * session, or US organisations see an empty Import Log.
 */
export function buildServiceUrl(
  service: string,
  opts?: { regionOverride?: ApiRegion },
): string {
  const host = `${branch}${service}.docbits.com`;
  const regionalHost = isRegionalStage()
    ? `${opts?.regionOverride ?? getCurrentApiRegion()}.${host}`
    : host;

  return `https://${regionalHost}`;
}

/**
 * True between the moment prepare-dashboard decides to switch region and the
 * moment the target cluster accepts the session token.
 *
 * During that window the target region answers every call with
 * `401 invalid_token` — it simply has not received the token yet. That is
 * replication lag, not a dead token, and the two are indistinguishable from the
 * response alone. Any client that reacts by refreshing sends the target region a
 * refresh_token it has never seen either; the grant is rejected with
 * `400 invalid_grant` and the failure path logs the session out. Every later
 * request then travels with no Authorization header, so the switch can never
 * complete and the user is stranded on /prepare-dashboard.
 */
export function isRegionSwitchInFlight(): boolean {
  try {
    return SessionStorage.getItem(REGION_SWITCH_STORAGE_KEY) != null;
  } catch {
    return false;
  }
}

export function getCurrentAuthRegion(): ApiRegion {
  const stored = LocalStorage.getItem(AUTH_REGION_STORAGE_KEY) as
    | string
    | null;
  return stored === 'us' ? 'us' : 'eu';
}

export function setAuthRegion(region: ApiRegion): void {
  LocalStorage.set(AUTH_REGION_STORAGE_KEY, region === 'us' ? 'us' : 'eu');
}

// The other of the two regions.
export function getOtherAuthRegion(region: ApiRegion): ApiRegion {
  return region === 'us' ? 'eu' : 'us';
}

export function clearPersistedAuthRegion(): void {
  LocalStorage.remove(AUTH_REGION_STORAGE_KEY);
}

export function buildAuthUrl(regionOverride?: ApiRegion): string {
  const authBranch = branch.startsWith('pre-prod') ? '' : branch;
  if (!isRegionalStage()) {
    return `https://${authBranch}auth.docbits.com`;
  }
  const region = regionOverride ?? getCurrentAuthRegion();
  return `https://${region}.${authBranch}auth.docbits.com`;
}

let lastSetRegion: ApiRegion | null = null;

/**
 * Persist the new region (encrypted). The first successful call in a
 * session (post-/profile handoff) never reloads. A later call that
 * flips the region triggers a full page reload so URL constants
 * rebuild — reserved for sub-org switches. Encrypt or storage failures
 * are logged and leave the prior state intact.
 */
export function setApiRegion(region: ApiRegion | undefined | null): void {
  const resolved: ApiRegion = region === 'us' ? 'us' : 'eu';

  try {
    LocalStorage.set(
      REGION_STORAGE_KEY,
      String(encryptionUtil.methods.generalEncryption(resolved)),
    );
  } catch (error) {
    console.error('[Region] Failed to persist api_region:', error);
    return;
  }

  const isFirstCallThisSession = lastSetRegion === null;
  const regionDidChange =
    !isFirstCallThisSession && resolved !== lastSetRegion;
  lastSetRegion = resolved;

  if (regionDidChange && typeof window !== 'undefined') {
    window.location.reload();
  }
}

export function clearPersistedApiRegion(): void {
  LocalStorage.remove(REGION_STORAGE_KEY);
}

// Convenience constants. Co-located so the listener-pattern shims below
// can hand back a URL without importing from APIs.ts (which would create
// a circular dependency).
export const DOC2API_URL = buildServiceUrl('api');
// WebSocket uses the api-sticky host — the dedicated sticky-nginx ingress with
// cookie affinity (keeps a client pinned to one ws pod) + CORS (DOCB-13416).
// The socket was dead because that ingress (`api-service-sticky`) pointed at
// the main `api-service`, which serves no /ws route -> 404; the fix repointed
// its backend to `api-websocket-service` (the dedicated ws pool). Do NOT move
// this to the plain `api` host: that ingress lacks CORS and sticky affinity.
// NOT channel-routed on purpose: the ws is a thin relay over the shared dev
// Redis pub/sub, so vesta + nova orgs use the same api-sticky host — a
// nova org still receives its events (published to the shared Redis).
export const WEB_SOCKET_URL = buildServiceUrl('api-sticky');

export function buildFaroCollectorUrl(): string {
  if (stage === 'local') {
    return '';
  }
  return `${buildServiceUrl('faro')}/collect`;
}

// ─── Transitional no-op shims ────────────────────────────────────────────
//
// In the new model the URL is correct at module load and a region change
// reloads the page, so per-call gating and listener callbacks are no
// longer load-bearing. These exports keep existing consumers compiling
// until a follow-up commit prunes the call sites.
//
// `whenRegionReady` resolves immediately because region is either
// persisted (loaded synchronously) or already defaulted to 'eu'.

export function whenRegionReady(): Promise<ApiRegion> {
  return Promise.resolve(getCurrentApiRegion());
}

export function isRegionReady(): boolean {
  return true;
}

export function onApiRegionChange(cb: (region: ApiRegion) => void): void {
  cb(getCurrentApiRegion());
}

export function onApiBaseUrlChange(cb: (url: string) => void): void {
  cb(DOC2API_URL);
}

export function persistApiRegion(region: ApiRegion | undefined | null): void {
  setApiRegion(region);
}
